<?php elseif($page==='admin/orders'):?><div class="page-heading"><span class="eyebrow">SİPARİŞ AKIŞI</span><h1>Siparişler</h1><p>Hazırlanıyor, kargoya verildi, yolda ve teslim edildi adımlarını buradan yönetin. Her güncelleme müşterinin takip ekranına yansır. İade işlemleri ödeme kuruluşunun panelinden ayrıca yapılmalıdır.</p></div><?php $q=trim((string)($_GET['q']??''));$pg=max(1,(int)($_GET['p']??1));$per=25;$where='';$args=[];if($q!==''){$where=' WHERE instr(lower(id),lower(?))>0 OR instr(lower(tracking_code),lower(?))>0 OR instr(lower(email),lower(?))>0 OR instr(lower(name),lower(?))>0 OR instr(phone,?)>0';$args=[$q,$q,$q,$q,$q];}$totalOrders=(int)query('SELECT COUNT(*) FROM orders'.$where,$args)->fetchColumn();$orders=query('SELECT * FROM orders'.$where.' ORDER BY created DESC LIMIT '.$per.' OFFSET '.(($pg-1)*$per),$args)->fetchAll();?><form method="get" class="filters"><input type="hidden" name="page" value="admin/orders"><input name="q" value="<?=e($q)?>" placeholder="Sipariş no, takip kodu, e-posta, ad veya telefon" aria-label="Sipariş ara"><button class="button">Ara</button></form><?php if(!$orders):?><div class="empty"><h2><?=$q!==''?'Aramanızla eşleşen sipariş yok.':'İlk siparişini bekliyoruz.'?></h2><p><?=$q!==''?'Farklı bir sipariş numarası, e-posta veya ad deneyin.':'Siparişler gelmeye başladığında burada görünecek.'?></p></div><?php endif;foreach($orders as $o):?><article class="panel order-admin"><div class="spread"><h2><?=e($o['id'])?></h2><span class="status"><?=e($statuses[$o['status']]??$o['status'])?></span></div><p><?=e($o['created'])?> · <?=money($o['total'])?> · <?=e($o['method'])?></p><details><summary>Müşteri ve ürün bilgileri</summary><p><?=e($o['name'])?> · <?=e($o['email'])?> · <?=e($o['phone'])?></p><p><?=nl2br(e($o['address']))?></p><?php foreach(json_decode($o['items'],true) as $p):?><p><?=e($p['name'])?> × <?=$p['qty']?> · <?=money($p['price']*$p['qty'])?></p><?php endforeach?></details><p class="tracking-code">Sipariş takip kodu: <strong><?=e($o['tracking_code'])?></strong></p><?php $next=orderNext($o);if($next):startform('order_update','filters');?><input type="hidden" name="id" value="<?=e($o['id'])?>"><select name="status" aria-label="Yeni sipariş durumu"><?php foreach($next as $s):?><option value="<?=$s?>"><?=$statuses[$s]?></option><?php endforeach?></select><input name="tracking" aria-label="Kargo takip bilgisi" placeholder="Kargo firması ve takip numarası" value="<?=e($o['tracking'])?>"><button class="button">Güncelle</button></form><?php endif?></article><?php endforeach;if($totalOrders>$per):?><div class="spread"><?php if($pg>1):?><a class="button" href="<?=e(url('admin/orders',['q'=>$q,'p'=>$pg-1]))?>">← Yeni siparişler</a><?php else:?><span></span><?php endif?><span>Sayfa <?=$pg?> / <?=(int)ceil($totalOrders/$per)?></span><?php if($pg*$per<$totalOrders):?><a class="button" href="<?=e(url('admin/orders',['q'=>$q,'p'=>$pg+1]))?>">Eski siparişler →</a><?php else:?><span></span><?php endif?></div><?php endif?>
<?php else:http_response_code(404);?><h1>Sayfa bulunamadı.</h1><?php endif?>
